<?php $editing = $item !== null; $field = static fn(string $name, mixed $default = '') => old($name, $item[$name] ?? $default); ?>
<section class="mb-6"><a href="<?= e(url('/pemutusan')) ?>" class="text-sm font-semibold text-primary hover:underline">← Kembali ke pemutusan</a><h1 class="mt-3 text-2xl font-bold text-slate-900"><?= e($title) ?></h1><p class="mt-1 text-sm text-slate-500">Catat tindakan pemutusan sesuai hasil lapangan.</p></section><form method="post" action="<?= e($action) ?>" class="rounded-2xl bg-white p-5 shadow-card sm:p-7"><?= csrf_field() ?><?php if ($editing): ?><input type="hidden" name="_method" value="PUT"><?php endif; ?><div class="grid gap-5 md:grid-cols-2"><div><label class="form-label" for="npa">NPA Pelanggan <span class="text-danger">*</span></label><input id="npa" name="npa" required <?= $editing ? 'readonly' : '' ?> value="<?= e($field('npa')) ?>" class="form-input" placeholder="Masukkan NPA"><p class="form-error"><?= e(error('npa') ?? '') ?></p></div><div><label class="form-label" for="tgl_pemutusan">Tanggal Pemutusan <span class="text-danger">*</span></label><input id="tgl_pemutusan" type="date" name="tgl_pemutusan" required value="<?= e($field('tgl_pemutusan', date('Y-m-d'))) ?>" class="form-input"><p class="form-error"><?= e(error('tgl_pemutusan') ?? '') ?></p></div><div><label class="form-label" for="status_pemutusan">Status Pemutusan <span class="text-danger">*</span></label><select id="status_pemutusan" name="status_pemutusan" class="form-input"><?php foreach (['Belum Diputus','Sudah Diputus','Selesai'] as $option): ?><option <?= $field('status_pemutusan', 'Belum Diputus') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="jenis_tindakan">Jenis Tindakan <span class="text-danger">*</span></label><select id="jenis_tindakan" name="jenis_tindakan" class="form-input"><?php foreach (['Angkat Meter','Potong Pipa Dinas','Tutup Lubang Bor'] as $option): ?><option <?= $field('jenis_tindakan') === $option ? 'selected' : '' ?>><?= e($option) ?></option><?php endforeach; ?></select></div><div><label class="form-label" for="biaya_tindakan">Biaya Tindakan <span class="text-danger">*</span></label><input id="biaya_tindakan" type="number" min="0" step="0.01" name="biaya_tindakan" required value="<?= e($field('biaya_tindakan', 0)) ?>" class="form-input"><p class="form-error"><?= e(error('biaya_tindakan') ?? '') ?></p></div><div class="md:col-span-2"><label class="form-label" for="keterangan">Keterangan</label><textarea id="keterangan" rows="3" name="keterangan" class="form-input" placeholder="Catatan tindakan lapangan (opsional)"><?= e($field('keterangan')) ?></textarea></div></div><div class="mt-7 flex justify-end gap-3 border-t border-slate-100 pt-5"><a href="<?= e(url('/pemutusan')) ?>" class="rounded-xl border border-slate-200 px-5 py-3 text-sm font-semibold text-slate-600">Batal</a><button class="rounded-xl bg-primary px-5 py-3 text-sm font-semibold text-white">Simpan Pemutusan</button></div></form>
